import { useState } from 'react';
import { Search, Plus, MoreHorizontal, X, Loader2 } from 'lucide-react';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Badge } from '../../../components/ui/Badge';
import { Avatar } from '../../../components/ui/Avatar';
import { IconButton } from '../../../components/ui/IconButton';
import { EmptyState } from '../../../components/ui/EmptyState';
import { useEmployeesList, useCreateEmployee, useDeleteEmployee } from '../../../services/employee-hooks';
import type { CreateEmployeeRequest } from '../../../services/employee-service';

const statusColors: Record<string, string> = {
  ACTIVE: 'success',
  ON_LEAVE: 'warning',
  PROBATION: 'info',
  TERMINATED: 'danger',
  ARCHIVED: 'neutral',
};

const typeColors: Record<string, string> = {
  FULL_TIME: 'accent',
  PART_TIME: 'info',
  CONTRACT: 'warning',
  INTERN: 'neutral',
};

export function EmployeesTab({ wsId, deptId }: { wsId: string; deptId: string }) {
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<CreateEmployeeRequest>({
    firstName: '', lastName: '', email: '', position: '', employmentType: 'FULL_TIME', startDate: '',
  });

  const { data, isLoading, isError } = useEmployeesList(wsId, deptId);
  const createEmp = useCreateEmployee(wsId, deptId);
  const deleteEmp = useDeleteEmployee(wsId, deptId);

  const employees = data?.content ?? [];

  const filtered = employees.filter((e) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return e.firstName.toLowerCase().includes(q) || e.lastName.toLowerCase().includes(q) || e.email.toLowerCase().includes(q) || e.position.toLowerCase().includes(q);
  });

  const handleCreate = () => {
    createEmp.mutate(form, {
      onSuccess: () => { setShowForm(false); setForm({ firstName: '', lastName: '', email: '', position: '', employmentType: 'FULL_TIME', startDate: '' }); },
    });
  };

  if (isLoading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-text-tertiary" /></div>;
  }

  if (isError) {
    return <div className="flex flex-col items-center justify-center py-20 gap-3"><p className="text-body font-medium text-danger-600">Failed to load employees</p><p className="text-caption text-text-tertiary">Please try again later.</p></div>;
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between gap-4">
        <Input placeholder="Search employees..." leftIcon={<Search />} value={search} onChange={(e) => setSearch(e.target.value)} containerClassName="max-w-sm" />
        <Button leftIcon={<Plus />} onClick={() => setShowForm(true)}>Add Employee</Button>
      </div>

      {showForm && (
        <Card>
          <CardBody className="flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h3 className="text-body font-semibold text-text-primary">New Employee</h3>
              <IconButton label="Close" variant="ghost" onClick={() => setShowForm(false)}><X className="h-4 w-4" /></IconButton>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <Input placeholder="First Name" value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} />
              <Input placeholder="Last Name" value={form.lastName} onChange={(e) => setForm({ ...form, lastName: e.target.value })} />
              <Input placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
              <Input placeholder="Position" value={form.position} onChange={(e) => setForm({ ...form, position: e.target.value })} />
              <Input placeholder="Start Date (YYYY-MM-DD)" value={form.startDate} onChange={(e) => setForm({ ...form, startDate: e.target.value })} />
              <select value={form.employmentType} onChange={(e) => setForm({ ...form, employmentType: e.target.value })}
                className="cx-input h-10 px-3">
                <option value="FULL_TIME">Full Time</option>
                <option value="PART_TIME">Part Time</option>
                <option value="CONTRACT">Contract</option>
                <option value="INTERN">Intern</option>
              </select>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button onClick={handleCreate} disabled={!form.firstName || !form.lastName || !form.email || !form.position || !form.startDate}>Create</Button>
            </div>
          </CardBody>
        </Card>
      )}

      {filtered.length === 0 ? (
        <EmptyState icon={<Search />} title="No employees found" description="Add employees to start managing your team." />
      ) : (
        <div className="space-y-2">
          {filtered.map((e) => (
            <div key={e.id} className="flex items-center gap-4 p-4 rounded-lg border border-border-subtle bg-surface hover:bg-surface-2 transition-colors">
              <Avatar name={`${e.firstName} ${e.lastName}`} size="sm" tone={0} />
              <div className="flex-1 min-w-0">
                <p className="text-body font-medium text-text-primary">{e.firstName} {e.lastName}</p>
                <p className="text-caption text-text-tertiary">{e.position} ÔÇó {e.employeeNumber}</p>
              </div>
              <div className="hidden sm:flex items-center gap-1">
                <Badge tone={(typeColors[e.employmentType] ?? 'neutral') as any} variant="soft">{e.employmentType.replace(/_/g, ' ')}</Badge>
                <Badge tone={(statusColors[e.employmentStatus] ?? 'neutral') as any} variant="soft">{e.employmentStatus.replace(/_/g, ' ')}</Badge>
              </div>
              <IconButton label="Delete" variant="ghost" size="sm" className="text-danger-600" onClick={() => deleteEmp.mutate(e.id)}>
                <X className="h-4 w-4" />
              </IconButton>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Search, Plus, CheckCircle, Circle, X, Loader2 } from 'lucide-react';
import { Card, CardBody, CardHeader, CardTitle } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Badge } from '../../../components/ui/Badge';
import { IconButton } from '../../../components/ui/IconButton';
import { Progress } from '../../../components/ui/Progress';
import { EmptyState } from '../../../components/ui/EmptyState';
import { useOnboardingList, useCreateOnboarding, useOnboardingTasks, useCompleteOnboardingTask, useOnboardingStats } from '../../../services/onboarding-hooks';

export function OnboardingTab({ wsId, deptId }: { wsId: string; deptId: string }) {
  const [expanded, setExpanded] = useState<string | null>(null);

  const { data, isLoading, isError } = useOnboardingList(wsId, deptId);
  const { data: stats } = useOnboardingStats(wsId, deptId);
  const { data: tasksData } = useOnboardingTasks(wsId, deptId, expanded ?? '');
  const createOnboarding = useCreateOnboarding(wsId, deptId);
  const completeTask = useCompleteOnboardingTask(wsId, deptId, expanded ?? '');

  const onboardings = data?.content ?? [];
  const tasks = tasksData ?? [];

  if (isLoading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-text-tertiary" /></div>;
  }

  if (isError) {
    return <div className="flex flex-col items-center justify-center py-20 gap-3"><p className="text-body font-medium text-danger-600">Failed to load onboarding</p><p className="text-caption text-text-tertiary">Please try again later.</p></div>;
  }

  return (
    <div className="flex flex-col gap-4">
      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Total</span>
            <span className="text-section font-bold text-text-primary">{stats.totalOnboardings}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Active</span>
            <span className="text-section font-bold text-warning-600">{stats.activeOnboardings}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Completed</span>
            <span className="text-section font-bold text-success-600">{stats.completedOnboardings}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Overdue Tasks</span>
            <span className="text-section font-bold text-danger-600">{stats.overdueTasks}</span>
          </div>
        </div>
      )}

      {onboardings.length === 0 ? (
        <EmptyState icon={<Plus />} title="No onboarding plans" description="Create onboarding plans for new employees." />
      ) : (
        <div className="space-y-3">
          {onboardings.map((o) => (
            <Card key={o.id}>
              <CardBody className="flex flex-col gap-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex h-9 w-9 items-center justify-center rounded-full bg-accent-100 text-accent-700 dark:bg-accent-900 dark:text-accent-300 text-caption font-semibold">
                      {o.employeeName?.split(' ').map((n: string) => n[0]).join('').slice(0, 2) ?? '??'}
                    </div>
                    <div>
                      <p className="text-body font-medium text-text-primary">{o.employeeName}</p>
                      <p className="text-2xs text-text-tertiary">{o.employeeNumber}</p>
                    </div>
                  </div>
                  <Badge tone={o.status === 'COMPLETED' ? 'success' : o.status === 'ACTIVE' ? 'warning' : 'info'} variant="soft">
                    {o.status}
                  </Badge>
                </div>

                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-2xs text-text-tertiary">Progress</span>
                    <span className="text-2xs font-medium text-text-primary">{o.completionPercentage}%</span>
                  </div>
                  <Progress value={o.completionPercentage} size="sm" tone={o.completionPercentage >= 80 ? 'success' : o.completionPercentage >= 40 ? 'warning' : 'info'} />
                </div>

                <div className="flex items-center gap-4 text-2xs text-text-tertiary">
                  <span>{o.completedTasks}/{o.totalTasks} tasks</span>
                  <span>Start: {o.startDate}</span>
                  {o.expectedCompletionDate && <span>Due: {o.expectedCompletionDate}</span>}
                </div>

                <Button variant="outline" size="sm" onClick={() => setExpanded(expanded === o.id ? null : o.id)}>
                  {expanded === o.id ? 'Hide Tasks' : 'View Tasks'} ({o.totalTasks})
                </Button>

                {expanded === o.id && (
                  <div className="flex flex-col gap-2 border-t border-border-subtle pt-3">
                    {tasks.length === 0 ? (
                      <p className="text-caption text-text-tertiary">No tasks loaded.</p>
                    ) : (
                      tasks.map((t) => (
                        <div key={t.id} className="flex items-center gap-3 p-2 rounded hover:bg-surface-2 transition-colors">
                          <button onClick={() => completeTask.mutate(t.id)} className="shrink-0">
                            {t.status === 'COMPLETED' ? (
                              <CheckCircle className="h-5 w-5 text-success-500" />
                            ) : (
                              <Circle className="h-5 w-5 text-text-tertiary" />
                            )}
                          </button>
                          <div className="flex-1 min-w-0">
                            <p className={cn('text-caption font-medium', t.status === 'COMPLETED' ? 'text-text-tertiary line-through' : 'text-text-primary')}>
                              {t.title}
                            </p>
                            {t.dueDate && <p className="text-2xs text-text-tertiary">Due: {t.dueDate}</p>}
                          </div>
                          <Badge tone={t.status === 'COMPLETED' ? 'success' : 'warning'} variant="soft">{t.status}</Badge>
                        </div>
                      ))
                    )}
                  </div>
                )}
              </CardBody>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function cn(...classes: (string | undefined | null | false)[]) {
  return classes.filter(Boolean).join(' ');
}

import { useState } from 'react';
import { Search, Plus, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Badge } from '../../../components/ui/Badge';
import { Progress } from '../../../components/ui/Progress';
import { EmptyState } from '../../../components/ui/EmptyState';
import { usePerformanceReviewsList, useCreatePerformanceReview, useSubmitPerformanceReview, useApprovePerformanceReview } from '../../../services/performance-review-hooks';

const statusColors: Record<string, string> = {
  DRAFT: 'neutral',
  SUBMITTED: 'info',
  APPROVED: 'success',
  REJECTED: 'danger',
  ARCHIVED: 'neutral',
};

const levelColors: Record<string, string> = {
  EXCELLENT: 'success',
  GOOD: 'info',
  AVERAGE: 'warning',
  BELOW_AVERAGE: 'danger',
  POOR: 'danger',
};

export function PerformanceReviewsTab({ wsId, deptId }: { wsId: string; deptId: string }) {
  const [search, setSearch] = useState('');

  const { data, isLoading, isError } = usePerformanceReviewsList(wsId, deptId);
  const submitReview = useSubmitPerformanceReview(wsId, deptId);
  const approveReview = useApprovePerformanceReview(wsId, deptId);

  const reviews = data?.content ?? [];

  const filtered = reviews.filter((r) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return r.employeeName?.toLowerCase().includes(q) || r.reviewerName?.toLowerCase().includes(q) || r.reviewPeriod?.toLowerCase().includes(q);
  });

  if (isLoading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-text-tertiary" /></div>;
  }

  if (isError) {
    return <div className="flex flex-col items-center justify-center py-20 gap-3"><p className="text-body font-medium text-danger-600">Failed to load performance reviews</p><p className="text-caption text-text-tertiary">Please try again later.</p></div>;
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between gap-4">
        <Input placeholder="Search reviews..." leftIcon={<Search />} value={search} onChange={(e) => setSearch(e.target.value)} containerClassName="max-w-sm" />
      </div>

      {filtered.length === 0 ? (
        <EmptyState icon={<Search />} title="No performance reviews found" description="Create reviews to evaluate employee performance." />
      ) : (
        <div className="space-y-3">
          {filtered.map((r) => (
            <Card key={r.id}>
              <CardBody className="flex flex-col gap-3">
                <div className="flex items-start justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <p className="text-body font-semibold text-text-primary">{r.employeeName}</p>
                      <Badge tone={(levelColors[r.performanceLevel] ?? 'neutral') as any} variant="soft">{r.performanceLevel}</Badge>
                    </div>
                    <p className="text-caption text-text-tertiary">Reviewer: {r.reviewerName}</p>
                  </div>
                  <div className="text-right">
                    <Badge tone={(statusColors[r.status] ?? 'neutral') as any} variant="soft">{r.status}</Badge>
                    <p className="text-2xs text-text-tertiary mt-1">{r.reviewPeriod}</p>
                  </div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <Criterion label="Objectives" value={r.objectivesAchieved} max={20} />
                  <Criterion label="Technical" value={r.technicalSkills} max={20} />
                  <Criterion label="Soft Skills" value={r.softSkills} max={20} />
                  <Criterion label="Punctuality" value={r.punctualityAttendance} max={20} />
                  <Criterion label="Teamwork" value={r.teamwork} max={20} />
                  <Criterion label="Initiative" value={r.initiativeProblemSolving} max={20} />
                  <Criterion label="Communication" value={r.communication} max={20} />
                  <Criterion label="Adaptability" value={r.continuousLearningAdaptability} max={20} />
                </div>

                <div className="flex items-center gap-4 pt-2 border-t border-border-subtle">
                  <div>
                    <span className="text-2xs text-text-tertiary">Total Score</span>
                    <p className="text-body font-bold text-text-primary">{r.totalScore}/{r.maxScore}</p>
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <Progress value={r.percentage ?? 0} size="sm" tone={(r.percentage ?? 0) >= 80 ? 'success' : (r.percentage ?? 0) >= 60 ? 'warning' : 'danger'} />
                      <span className="text-caption font-medium text-text-primary">{(r.percentage ?? 0).toFixed(0)}%</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    {r.status === 'DRAFT' && (
                      <Button size="sm" variant="outline" onClick={() => submitReview.mutate(r.id)}>
                        Submit
                      </Button>
                    )}
                    {r.status === 'SUBMITTED' && (
                      <Button size="sm" variant="outline" className="text-success-600" onClick={() => approveReview.mutate(r.id)}>
                        <CheckCircle className="h-4 w-4 mr-1" /> Approve
                      </Button>
                    )}
                  </div>
                </div>
              </CardBody>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function Criterion({ label, value, max }: { label: string; value?: number; max: number }) {
  const pct = value != null ? (value / max) * 100 : 0;
  return (
    <div className="flex flex-col gap-1 p-2 rounded border border-border-subtle">
      <div className="flex items-center justify-between">
        <span className="text-2xs text-text-tertiary">{label}</span>
        <span className="text-2xs font-medium text-text-primary">{value ?? '-'}/{max}</span>
      </div>
      <Progress value={pct} size="xs" tone={pct >= 80 ? 'success' : pct >= 60 ? 'warning' : 'danger'} />
    </div>
  );
}

