              </button>
            ))}
          </CardBody>
        </Card>

        {/* Recent Activity */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Flame className="h-5 w-5" />
              Recent Activity
            </CardTitle>
          </CardHeader>
          <CardBody className="space-y-3">
            {recentActivity.slice(0, 5).map((activity) => {
              const article = knowledgeArticles.find((a) => a.id === activity.article);
              return (
                <div key={activity.id} className="py-2 border-b border-border-subtle last:border-0">
                  <p className="text-caption font-medium text-text-primary">
                    <span className="text-text-secondary">{activity.author}</span> {activity.type === 'published' ? '­ƒôñ' : activity.type === 'updated' ? 'Ô£Å´©Å' : '­ƒôØ'} {activity.type === 'published' ? 'published' : activity.type === 'updated' ? 'updated' : 'created'}
                  </p>
                  <p className="text-2xs text-text-tertiary mt-1 line-clamp-1">
                    "{article?.title}"
