import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Settings, Save, Archive, Trash2, AlertTriangle, ArrowLeft, Building2, ExternalLink, Clock } from 'lucide-react';
import { Card, CardBody, CardHeader, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { Skeleton } from '../../components/ui/Skeleton';
import { EmptyState } from '../../components/ui/EmptyState';
import { useToast } from '../../components/ui/Toast';
import { useWorkspaceDetail, useUpdateWorkspace, useArchiveWorkspace, useDeleteWorkspace } from '../../services/workspace-hooks';
import { useWorkspaceId } from '../../hooks/useWorkspaceId';

const statusVariant: Record<string, 'success' | 'warning' | 'info' | 'neutral'> = {
  active: 'success',
  archived: 'neutral',
  suspended: 'warning',
};

export function WorkspaceSettingsPage() {
  const navigate = useNavigate();
  const workspaceId = useWorkspaceId();
  const { toast } = useToast();
  const { data: workspace, isLoading, isError, error } = useWorkspaceDetail(workspaceId);
  const updateMutation = useUpdateWorkspace(workspaceId);
  const archiveMutation = useArchiveWorkspace();
  const deleteMutation = useDeleteWorkspace();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [initialized, setInitialized] = useState(false);

  if (!initialized && workspace) {
    setName(workspace.name);
    setDescription(workspace.description ?? '');
    setInitialized(true);
  }

  const handleSave = () => {
    if (!name.trim()) return;
    updateMutation.mutate(
      { name: name.trim(), description: description.trim() || undefined },
      {
        onSuccess: () => toast({ title: 'Workspace updated successfully', tone: 'success' }),
        onError: () => toast({ title: 'Failed to update workspace', tone: 'error' }),
      },
    );
  };

  const handleArchive = () => {
    if (!window.confirm('Are you sure you want to archive this workspace? It can be restored later.')) return;
    archiveMutation.mutate(workspaceId, {
      onSuccess: () => {
        toast({ title: 'Workspace archived', tone: 'success' });
        navigate('/app/all-workspaces');
      },
      onError: () => toast({ title: 'Failed to archive workspace', tone: 'error' }),
    });
  };

  const handleDelete = () => {
    if (!window.confirm('Are you sure you want to permanently delete this workspace? This action cannot be undone.')) return;
    deleteMutation.mutate(workspaceId, {
      onSuccess: () => {
        toast({ title: 'Workspace deleted', tone: 'success' });
        navigate('/app/all-workspaces');
      },
      onError: () => toast({ title: 'Failed to delete workspace', tone: 'error' }),
    });
  };

  if (isLoading) {
    return (
      <div className="flex flex-col gap-6 animate-fade-in">
        <div className="flex flex-col gap-1.5">
          <Skeleton className="h-7 w-56" />
          <Skeleton className="h-5 w-80" />
        </div>
        <div className="flex flex-col gap-6 lg:flex-row lg:gap-8">
          <nav className="flex shrink-0 flex-col gap-0.5 lg:w-56">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-full" />
            ))}
          </nav>
          <div className="flex-1 min-w-0 space-y-6">
            <Card>
              <CardHeader>
                <Skeleton className="h-6 w-40" />
                <Skeleton className="h-4 w-60" />
              </CardHeader>
              <CardBody className="space-y-5">
                {Array.from({ length: 4 }).map((_, i) => (
                  <Skeleton key={i} className="h-10 w-full" />
                ))}
              </CardBody>
            </Card>
          </div>
        </div>
      </div>
    );
  }

  if (isError || !workspace) {
    return (
      <EmptyState
        icon={<AlertTriangle />}
        title="Failed to load workspace"
        description={error instanceof Error ? error.message : 'Could not load workspace settings. Please try again.'}
        action={<Button leftIcon={<ArrowLeft />} onClick={() => navigate('/app/all-workspaces')}>Back to Workspaces</Button>}
      />
    );
  }

  const isSaving = updateMutation.isPending;
  const canSave = name.trim() !== '' && name.trim() !== workspace.name || description.trim() !== (workspace.description ?? '');

  return (
    <div className="flex flex-col gap-6 animate-fade-in">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex flex-col gap-1.5">
          <div className="flex items-center gap-2">
            <Settings className="h-5 w-5 text-text-tertiary" />
            <h1 className="text-page font-semibold text-text-primary">Workspace Settings</h1>
          </div>
          <p className="text-body text-text-secondary">
            Manage workspace name, description, and advanced actions.
          </p>
        </div>
        <Button variant="ghost" size="sm" leftIcon={<ArrowLeft />} onClick={() => navigate(-1)}>
          Back
        </Button>
      </div>

      {/* General Information */}
      <Card>
        <CardHeader>
          <div className="flex items-start justify-between gap-4">
            <div>
              <CardTitle>General Information</CardTitle>
              <p className="text-caption text-text-secondary mt-1">
                Basic workspace details and identification.
              </p>
            </div>
            <Button
              size="sm"
              leftIcon={isSaving ? undefined : <Save />}
              onClick={handleSave}
              disabled={!canSave || isSaving}
              loading={isSaving}
            >
              {isSaving ? 'Saving...' : 'Save'}
            </Button>
          </div>
        </CardHeader>
        <CardBody className="space-y-5">
          <Input
            label="Workspace Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            helperText="Your workspace name visible to all members."
          />
          <Input
            label="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            helperText="Brief description of your workspace purpose."
          />
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Input
              label="Owner"
              value={`${workspace.owner.firstName} ${workspace.owner.lastName}`}
              disabled
            />
            <div>
              <p className="text-caption font-medium text-text-secondary mb-1.5">Status</p>
              <Badge variant={statusVariant[workspace.status] ?? 'neutral'}>
                {workspace.status.charAt(0).toUpperCase() + workspace.status.slice(1)}
              </Badge>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Input label="Created" value={new Date(workspace.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })} disabled />
            <Input label="Updated" value={new Date(workspace.updatedAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })} disabled />
          </div>
          <Input label="Workspace ID" value={workspace.id} disabled />
        </CardBody>
      </Card>

      {/* Danger Zone */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-danger-600">
            <AlertTriangle className="h-4 w-4" />
            Danger Zone
          </CardTitle>
        </CardHeader>
        <CardBody className="space-y-6">
          <div className="rounded-lg border border-danger-200 bg-danger-50 dark:border-danger-800 dark:bg-danger-100 p-4">
            <div className="flex items-start gap-3">
              <Archive className="h-5 w-5 text-danger-500 shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-body font-semibold text-danger-700 dark:text-danger-200">Archive Workspace</p>
                <p className="text-caption text-danger-600 dark:text-danger-300 mt-1">
                  Archiving will deactivate the workspace. Members will lose access until it is restored. Archived workspaces can be restored later.
                </p>
                <Button
                  variant="danger"
                  size="sm"
                  className="mt-3"
                  leftIcon={<Archive />}
                  onClick={handleArchive}
                  loading={archiveMutation.isPending}
                  disabled={archiveMutation.isPending}
                >
                  Archive Workspace
                </Button>
              </div>
            </div>
          </div>

          <div className="rounded-lg border border-danger-200 bg-danger-50 dark:border-danger-800 dark:bg-danger-100 p-4">
            <div className="flex items-start gap-3">
              <Trash2 className="h-5 w-5 text-danger-500 shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-body font-semibold text-danger-700 dark:text-danger-200">Delete Workspace</p>
                <p className="text-caption text-danger-600 dark:text-danger-300 mt-1">
                  Deleting your workspace is permanent and cannot be undone. All data, projects, and member information will be permanently removed.
                </p>
                <Button
                  variant="danger"
                  size="sm"
                  className="mt-3"
                  leftIcon={<Trash2 />}
                  onClick={handleDelete}
                  loading={deleteMutation.isPending}
                  disabled={deleteMutation.isPending}
                >
                  Delete Workspace
                </Button>
              </div>
            </div>
          </div>
        </CardBody>
      </Card>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { MessageSquare, AtSign, Activity, Loader2, Users, AlertCircle, Search } from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { Avatar } from '../../components/ui/Avatar';
import { EmptyState } from '../../components/ui/EmptyState';
import { usePersonalDashboard } from '../../services/workspace-hooks';
import { useWorkspaceAnalytics } from '../../services/department-hooks';
import { cn } from '../../lib/cn';

interface FeedItem {
  id: string;
  type: 'comment' | 'mention' | 'activity';
  authorName: string;
  content: string;
  context: string;
  timestamp: string;
}

export function CollaborationPage() {
  const [searchParams] = useSearchParams();
  const workspaceId = searchParams.get('ws') ?? '';
  const [search, setSearch] = useState('');
  const [feedType, setFeedType] = useState<'all' | 'comments' | 'mentions' | 'activity'>('all');

  const { data: dashboard, isLoading: dashLoading, isError: dashError } = usePersonalDashboard(workspaceId || undefined);
  const { data: analytics, isLoading: anLoading } = useWorkspaceAnalytics(workspaceId || undefined) as { data: { commentCount?: number; memberCount?: number } | undefined; isLoading: boolean };

  const feedItems: FeedItem[] = useMemo(() => {
    const items: FeedItem[] = [];
    if (dashboard) {
      dashboard.recentComments?.forEach((c) => {
        items.push({
          id: `c-${c.id}`,
          type: 'comment',
          authorName: c.authorName ?? 'Unknown',
          content: c.content,
          context: c.taskTitle ?? 'Task',
          timestamp: c.createdAt,
        });
      });
      dashboard.unreadMentions?.forEach((m) => {
        items.push({
          id: `m-${m.id}`,
          type: 'mention',
          authorName: m.mentionedBy ?? 'Someone',
          content: m.content,
          context: 'Mention',
          timestamp: m.createdAt,
        });
      });
      dashboard.recentActivities?.forEach((a) => {
        items.push({
          id: `a-${a.id}`,
          type: 'activity',
          authorName: a.actorName ?? 'System',
          content: a.description,
          context: a.projectName ?? 'General',
          timestamp: a.createdAt,
        });
      });
      dashboard.workspaceActivities?.forEach((a) => {
        items.push({
          id: `wa-${a.id}`,
          type: 'activity',
          authorName: a.actorName ?? 'System',
          content: a.description,
          context: a.projectName ?? 'General',
          timestamp: a.createdAt,
        });
      });
    }
    return items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [dashboard]);

  const filteredItems = useMemo(() => {
    let result = feedItems;
    if (search) {
      const q = search.toLowerCase();
      result = result.filter((i) =>
        i.authorName.toLowerCase().includes(q) ||
        i.content.toLowerCase().includes(q) ||
        i.context.toLowerCase().includes(q)
      );
    }
    if (feedType !== 'all') {
      result = result.filter((i) => i.type === feedType);
    }
    return result;
  }, [feedItems, search, feedType]);

  const commentCount = dashboard?.recentComments?.length ?? 0;
  const mentionCount = dashboard?.unreadMentions?.length ?? 0;
  const activityCount = (dashboard?.recentActivities?.length ?? 0) + (dashboard?.workspaceActivities?.length ?? 0);

  if (dashLoading || anLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-text-tertiary" />
      </div>
    );
  }

  if (dashError) {
    return (
      <div className="flex flex-col items-center justify-center py-20">
        <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl bg-danger-50 text-danger-500 dark:bg-danger-500/10">
          <AlertCircle className="h-6 w-6" />
        </div>
        <h3 className="text-section font-semibold text-text-primary">Unable to load collaboration data</h3>
        <p className="mt-1 text-body text-text-tertiary">Please try again later.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-1.5">
        <h1 className="text-page font-semibold text-text-primary">Collaboration</h1>
        <p className="text-body text-text-secondary">
          Discuss, collaborate, and stay connected with your team.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard icon={<MessageSquare />} label="Comments" value={commentCount} />
        <StatCard icon={<AtSign />} label="Mentions" value={mentionCount} />
        <StatCard icon={<Activity />} label="Activities" value={activityCount} />
      </div>

      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 flex-col gap-2 sm:flex-row sm:gap-2">
          <Input
            placeholder="Search feed..."
            leftIcon={<Search />}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            containerClassName="w-full sm:max-w-xs"
          />
          <div className="flex gap-1">
            {(['all', 'comments', 'mentions', 'activity'] as const).map((t) => (
              <Button
                key={t}
                variant={feedType === t ? 'primary' : 'outline'}
                size="sm"
                onClick={() => setFeedType(t)}
              >
                {t === 'all' ? 'All' : t.charAt(0).toUpperCase() + t.slice(1)}
              </Button>
            ))}
          </div>
        </div>
      </div>

      {filteredItems.length === 0 ? (
        <EmptyState
          icon={<MessageSquare />}
          title="No activity yet"
          description="Collaboration feed will populate as your team works on projects."
        />
      ) : (
        <div className="space-y-3">
          {filteredItems.map((item) => (
            <FeedCard key={item.id} item={item} />
          ))}
        </div>
      )}
    </div>
  );
}

function StatCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: number }) {
  return (
    <div className="flex items-center gap-3 rounded-lg border border-border-subtle bg-surface p-4">
      <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-300 [&>svg]:h-[18px] [&>svg]:w-[18px]">
        {icon}
      </span>
      <div>
        <p className="text-2xs text-text-tertiary">{label}</p>
        <p className="text-body font-bold text-text-primary">{value}</p>
      </div>
    </div>
  );
}

function FeedCard({ item }: { item: FeedItem }) {
  const typeColor = item.type === 'comment' ? 'accent' : item.type === 'mention' ? 'warning' : 'info';
  const typeLabel = item.type === 'comment' ? 'Comment' : item.type === 'mention' ? 'Mention' : 'Activity';
  return (
    <Card className="hover:border-border-default transition-colors">
      <CardBody className="space-y-2">
        <div className="flex items-center gap-2">
          <Avatar name={item.authorName} size="sm" />
          <p className="text-body font-semibold text-text-primary">{item.authorName}</p>
          <Badge tone={typeColor} variant="soft">{typeLabel}</Badge>
          <span className="text-2xs text-text-tertiary ml-auto">
            {new Date(item.timestamp).toLocaleDateString()}
          </span>
        </div>
        <p className="text-body text-text-secondary leading-relaxed">{item.content}</p>
        {item.context && item.type !== 'mention' && (
          <Badge tone="neutral" variant="soft">{item.context}</Badge>
        )}
      </CardBody>
    </Card>
  );
}

import { useState, useMemo } from 'react';
import { useToast } from '../../components/ui/Toast';
import {
  ArrowLeft,
  CheckCircle2,
  AlertCircle,
  Clock,
  Users,
  FileText,
  Calendar,
  MoreHorizontal,
  Edit2,
  Archive,
  Share2,
  Plus,
  Send,
  Paperclip,
  Smile,
  X,
  Trash2,
  ListChecks,
  RotateCcw,
} from 'lucide-react';
import { Card, CardBody, CardHeader, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge, type Tone } from '../../components/ui/Badge';
import { Avatar } from '../../components/ui/Avatar';
import { IconButton } from '../../components/ui/IconButton';
import { Progress } from '../../components/ui/Progress';
import { Textarea } from '../../components/ui/Textarea';
import { Checkbox } from '../../components/ui/Checkbox';
import { Tabs, type TabItem } from '../../components/ui/Tabs';
import { Dropdown, type DropdownItem } from '../../components/ui/Dropdown';
import { Timeline, type TimelineItem } from '../../components/ui/Timeline';
import { Skeleton } from '../../components/ui/Skeleton';
import { EmptyState } from '../../components/ui/EmptyState';
import { Input } from '../../components/ui/Input';
import {
  useTaskDetail,
  useUpdateTask,
  useDeleteTask,
  useCommentsList,
  useCreateComment,
  useDeleteComment,
  useAttachmentsList,
  useActivitiesList,
  useChecklistsList,
  useCreateChecklist,
  useDeleteChecklist,
  useCreateChecklistItem,
  useUpdateChecklistItem,
  useDeleteChecklistItem,
} from '../../services/task-hooks';
import {
  mapTaskResponse,
  mapCommentResponse,
  mapAttachmentResponse,
  mapActivityResponse,
} from './tasks-types';
import type { Task, ChecklistResponse } from './tasks-types';
import { TaskModal, type TaskModalKind } from './TaskModals';

const statusColor: Record<string, Tone> = {
  todo: 'info',
  'in-progress': 'accent',
  'in-review': 'warning',
  blocked: 'danger',
  completed: 'success',
  archived: 'neutral',
};

const statusLabels: Record<string, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  'in-review': 'In Review',
  blocked: 'Blocked',
  completed: 'Completed',
  archived: 'Archived',
};

interface TaskDetailsPageProps {
  taskId: string;
  workspaceId?: string;
  departmentId?: string;
  projectId?: string;
  onBack?: () => void;
}

export function TaskDetailsPage({ taskId, workspaceId = '', departmentId = '', projectId = '', onBack }: TaskDetailsPageProps) {
  const [activeTab, setActiveTab] = useState('overview');
  const [commentText, setCommentText] = useState('');
  const [newChecklistTitle, setNewChecklistTitle] = useState('');
  const [newItemText, setNewItemText] = useState<Record<string, string>>({});
  const [editingItem, setEditingItem] = useState<Record<string, string>>({});
  const [modal, setModal] = useState<TaskModalKind>(null);
  const { toast } = useToast();

  const { data: taskData, isLoading: taskLoading, isError: taskError } = useTaskDetail(workspaceId, departmentId, projectId, taskId);
  const { data: commentsPage } = useCommentsList(workspaceId, departmentId, projectId, taskId);
  const { data: attachmentsPage } = useAttachmentsList(workspaceId, departmentId, projectId, taskId);
  const { data: activitiesPage } = useActivitiesList(workspaceId, departmentId, projectId, taskId);
  const { data: checklistsData } = useChecklistsList(workspaceId, departmentId, projectId, taskId);

  const updateTask = useUpdateTask(workspaceId, departmentId, projectId, taskId);
  const deleteTask = useDeleteTask(workspaceId, departmentId, projectId);
  const createComment = useCreateComment(workspaceId, departmentId, projectId, taskId);
  const deleteComment = useDeleteComment(workspaceId, departmentId, projectId, taskId);
  const createChecklist = useCreateChecklist(workspaceId, departmentId, projectId, taskId);
  const deleteChecklist = useDeleteChecklist(workspaceId, departmentId, projectId, taskId);
  const createItem = useCreateChecklistItem(workspaceId, departmentId, projectId, taskId);
  const updateItem = useUpdateChecklistItem(workspaceId, departmentId, projectId, taskId);
  const deleteItem = useDeleteChecklistItem(workspaceId, departmentId, projectId, taskId);

  const task: Task | null = useMemo(() => {
    if (!taskData) return null;
    return mapTaskResponse(taskData);
  }, [taskData]);

  const comments = useMemo(() => {
    if (!commentsPage?.content) return [];
    return commentsPage.content.map(mapCommentResponse);
  }, [commentsPage]);

  const attachments = useMemo(() => {
    if (!attachmentsPage?.content) return [];
    return attachmentsPage.content.map(mapAttachmentResponse);
  }, [attachmentsPage]);

  const activities = useMemo(() => {
    if (!activitiesPage?.content) return [];
    return activitiesPage.content.map(mapActivityResponse);
  }, [activitiesPage]);

  const timelineItems: TimelineItem[] = useMemo(() => {
    return activities.map((a) => ({
      id: a.id,
      title: a.description,
      timestamp: a.timestamp,
      tone: 'neutral' as const,
    }));
  }, [activities]);

  const tabItems: TabItem[] = [
    { id: 'overview', label: 'Overview' },
    { id: 'checklist', label: 'Checklist', count: checklistsData?.length ?? 0 },
    { id: 'activity', label: 'Activity' },
    { id: 'comments', label: 'Comments', count: comments.length },
    { id: 'attachments', label: 'Attachments', count: attachments.length },
  ];

  const handleAddComment = () => {
    if (!commentText.trim()) return;
    createComment.mutate({ content: commentText.trim() }, {
      onSuccess: () => { setCommentText(''); toast({ title: 'Comment added', tone: 'success' }); },
      onError: () => toast({ title: 'Failed to add comment', tone: 'danger' }),
    });
  };

  const handleAddChecklist = () => {
    if (!newChecklistTitle.trim()) return;
    createChecklist.mutate({ title: newChecklistTitle.trim() }, {
      onSuccess: () => { setNewChecklistTitle(''); toast({ title: 'Checklist created', tone: 'success' }); },
      onError: () => toast({ title: 'Failed to create checklist', tone: 'danger' }),
    });
  };

  const handleAddItem = (checklistId: string) => {
    const text = newItemText[checklistId]?.trim();
    if (!text) return;
    createItem.mutate({ checklistId, data: { title: text } }, {
      onSuccess: () => { setNewItemText((prev) => ({ ...prev, [checklistId]: '' })); },
      onError: () => toast({ title: 'Failed to add item', tone: 'danger' }),
    });
  };

  const handleToggleItem = (checklistId: string, itemId: string, completed: boolean) => {
    updateItem.mutate({ checklistId, itemId, data: { completed: !completed } });
  };

  const handleSaveItemTitle = (checklistId: string, itemId: string) => {
    const text = editingItem[`${itemId}-title`]?.trim();
    if (!text) return;
    updateItem.mutate({ checklistId, itemId, data: { title: text } }, {
      onSuccess: () => setEditingItem((prev) => ({ ...prev, [`${itemId}-title`]: '' })),
    });
  };

  if (taskLoading) {
    return (
      <div className="flex flex-col gap-6">
        <Skeleton className="h-8 w-64" />
        <Skeleton className="h-6 w-48" />
        <Skeleton className="h-96 rounded-lg" />
      </div>
    );
  }

  if (taskError || !task) {
    return (
      <EmptyState
        icon={<AlertCircle />}
        title="Task not found"
        description="The task could not be loaded. It may have been deleted or you may not have access."
      />
    );
  }

  const detailActionItems: DropdownItem[] = [
    { label: 'Edit', icon: <Edit2 className="h-4 w-4" />, onClick: () => setModal({ kind: 'edit', task: { id: task.id, title: task.title, description: task.description } }) },
    { divider: true, label: 'Danger zone' },
    { label: 'Archive', icon: <Archive className="h-4 w-4" />, onClick: () => setModal({ kind: 'archive', task: { id: task.id, title: task.title } }) },
    { label: 'Delete', icon: <Trash2 className="h-4 w-4" />, onClick: () => setModal({ kind: 'delete', task: { id: task.id, title: task.title } }) },
  ];

  return (
    <div className="flex flex-col gap-6">
      <TaskModal state={modal} onClose={() => setModal(null)} onSubmit={(data) => {
        if (!modal) return;
        switch (modal.kind) {
          case 'edit':
            updateTask.mutate({ title: data.title, description: data.description }, {
              onSuccess: () => toast({ title: 'Task updated', tone: 'success' }),
              onError: () => toast({ title: 'Failed to update task', tone: 'danger' }),
            });
            break;
          case 'archive':
            deleteTask.mutate(modal.task.id, {
              onSuccess: () => { toast({ title: 'Task archived', tone: 'success' }); if (onBack) onBack(); },
            });
            break;
          case 'delete':
            deleteTask.mutate(modal.task.id, {
              onSuccess: () => { toast({ title: 'Task deleted', tone: 'success' }); if (onBack) onBack(); },
            });
            break;
        }
        setModal(null);
      }} />

      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          {onBack && (
            <IconButton label="Back" variant="ghost" size="sm" onClick={onBack}>
              <ArrowLeft className="h-4 w-4" />
            </IconButton>
          )}
          <div className="flex flex-col">
            <div className="flex items-center gap-3">
              <h1 className="text-page font-semibold text-text-primary">{task.title}</h1>
              <Badge tone={statusColor[task.status]} variant="soft" dot>
                {statusLabels[task.status]}
              </Badge>
              <Badge tone={task.priority === 'urgent' ? 'danger' : task.priority === 'high' ? 'warning' : task.priority === 'medium' ? 'info' : 'success'} variant="soft">
                {task.priority}
              </Badge>
            </div>
            <p className="text-body text-text-secondary mt-1">{task.projectName}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            }
            items={detailActionItems}
            align="right"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <Tabs tabs={tabItems} activeTab={activeTab} onChange={setActiveTab} />

          <div className="mt-4">
            {activeTab === 'overview' && (
              <Card>
                <CardBody className="space-y-4">
                  <div>
                    <h3 className="text-caption font-semibold text-text-primary mb-1">Description</h3>
                    <p className="text-body text-text-secondary">{task.description || 'No description provided.'}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4 pt-2 border-t border-border-subtle">
                    <InfoRow icon={<Calendar />} label="Created" value={task.createdAt} />
                    <InfoRow icon={<Clock />} label="Deadline" value={task.deadline || 'No deadline'} />
                    {task.assigneeName && <InfoRow icon={<Users />} label="Assignee" value={task.assigneeName} />}
                    {task.startDate && <InfoRow icon={<Clock />} label="Start Date" value={task.startDate} />}
                  </div>
                </CardBody>
              </Card>
            )}

            {activeTab === 'checklist' && (
              <div className="space-y-4">
                <div className="flex items-center gap-2">
                  <Input
                    placeholder="New checklist title..."
                    value={newChecklistTitle}
                    onChange={(e) => setNewChecklistTitle(e.target.value)}
                    containerClassName="flex-1"
                  />
                  <Button onClick={handleAddChecklist} disabled={!newChecklistTitle.trim()} leftIcon={<Plus className="h-4 w-4" />}>Add</Button>
                </div>
                {(!checklistsData || checklistsData.length === 0) ? (
                  <Card><CardBody className="py-8 text-center"><p className="text-body text-text-secondary">No checklists yet. Create one above.</p></CardBody></Card>
                ) : (
                  checklistsData.map((cl) => (
                    <Card key={cl.id}>
                      <CardHeader className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <ListChecks className="h-4 w-4 text-text-tertiary" />
                          <CardTitle>{cl.title}</CardTitle>
                          <Badge tone="neutral" variant="soft">{cl.completedItems}/{cl.totalItems}</Badge>
                        </div>
                        <div className="flex items-center gap-2">
                          <Progress value={cl.completionPercentage} size="sm" className="w-20" />
                          <IconButton label="Delete checklist" variant="ghost" size="sm" onClick={() => deleteChecklist.mutate(cl.id, { onSuccess: () => toast({ title: 'Checklist deleted', tone: 'success' }) })}>
                            <Trash2 className="h-4 w-4 text-danger-500" />
                          </IconButton>
                        </div>
                      </CardHeader>
                      <CardBody className="space-y-1">
                        {cl.items?.map((item) => (
                          <div key={item.id} className="flex items-center gap-2 py-1">
                            <Checkbox checked={item.completed} onChange={() => handleToggleItem(cl.id, item.id, item.completed)} />
                            {editingItem[`${item.id}-title`] != null && editingItem[`${item.id}-title`] !== undefined ? (
                              <Input
                                value={editingItem[`${item.id}-title`] ?? item.title}
                                onChange={(e) => setEditingItem((prev) => ({ ...prev, [`${item.id}-title`]: e.target.value }))}
                                onBlur={() => handleSaveItemTitle(cl.id, item.id)}
                                onKeyDown={(e) => { if (e.key === 'Enter') handleSaveItemTitle(cl.id, item.id); }}
                                autoFocus
                                containerClassName="flex-1"
                              />
                            ) : (
                              <span
                                className={`flex-1 text-body ${item.completed ? 'line-through text-text-tertiary' : 'text-text-primary'}`}
                                onDoubleClick={() => setEditingItem((prev) => ({ ...prev, [`${item.id}-title`]: item.title }))}
                              >
                                {item.title}
                              </span>
                            )}
                            <IconButton label="Delete item" variant="ghost" size="sm" onClick={() => deleteItem.mutate({ checklistId: cl.id, itemId: item.id })}>
                              <X className="h-3 w-3 text-text-tertiary" />
                            </IconButton>
                          </div>
                        ))}
                        <div className="flex items-center gap-2 pt-2">
                          <Input
                            placeholder="Add item..."
                            value={newItemText[cl.id] ?? ''}
                            onChange={(e) => setNewItemText((prev) => ({ ...prev, [cl.id]: e.target.value }))}
                            onKeyDown={(e) => { if (e.key === 'Enter') handleAddItem(cl.id); }}
                            containerClassName="flex-1"
                          />
                          <IconButton label="Add item" variant="ghost" size="sm" onClick={() => handleAddItem(cl.id)}>
                            <Plus className="h-4 w-4" />
                          </IconButton>
                        </div>
                      </CardBody>
                    </Card>
                  ))
                )}
              </div>
            )}

            {activeTab === 'activity' && (
              <Card>
                <CardBody>
                  {timelineItems.length === 0 ? (
                    <p className="text-body text-text-secondary py-4 text-center">No activity recorded yet.</p>
                  ) : (
                    <Timeline items={timelineItems} />
                  )}
                </CardBody>
              </Card>
            )}

            {activeTab === 'comments' && (
              <Card>
                <CardBody className="space-y-4">
                  <div className="flex gap-2">
                    <Textarea
                      placeholder="Write a comment..."
                      value={commentText}
                      onChange={(e) => setCommentText(e.target.value)}
                      className="flex-1"
                    />
                    <Button onClick={handleAddComment} disabled={!commentText.trim()} leftIcon={<Send className="h-4 w-4" />}>Send</Button>
                  </div>
                  {comments.length === 0 ? (
                    <p className="text-body text-text-secondary py-4 text-center">No comments yet.</p>
                  ) : (
                    comments.map((c) => (
                      <div key={c.id} className="flex gap-3 py-3 border-b border-border-subtle last:border-0">
                        <Avatar name={c.author || 'User'} size="sm" tone={0} />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <span className="text-caption font-medium text-text-primary">{c.author || 'User'}</span>
                            <span className="text-2xs text-text-tertiary">{c.timestamp}</span>
                          </div>
                          <p className="text-body text-text-secondary mt-1">{c.content}</p>
                        </div>
                        <IconButton label="Delete comment" variant="ghost" size="sm" onClick={() => deleteComment.mutate(c.id)}>
                          <X className="h-3 w-3 text-text-tertiary" />
                        </IconButton>
                      </div>
                    ))
                  )}
                </CardBody>
              </Card>
            )}

            {activeTab === 'attachments' && (
              <Card>
                <CardBody>
                  {attachments.length === 0 ? (
                    <p className="text-body text-text-secondary py-4 text-center">No attachments yet.</p>
                  ) : (
                    <div className="grid grid-cols-2 gap-3">
                      {attachments.map((a) => (
                        <div key={a.id} className="flex items-center gap-3 p-3 rounded-lg border border-border-subtle">
                          <FileText className="h-8 w-8 text-text-tertiary" />
                          <div className="min-w-0">
                            <p className="text-caption font-medium text-text-primary truncate">{a.name}</p>
                            <p className="text-2xs text-text-tertiary">{a.type}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </CardBody>
              </Card>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Details</CardTitle>
            </CardHeader>
            <CardBody className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-caption text-text-tertiary">Status</span>
                <Badge tone={statusColor[task.status]} variant="soft" dot>{statusLabels[task.status]}</Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-caption text-text-tertiary">Priority</span>
                <Badge tone={task.priority === 'urgent' ? 'danger' : task.priority === 'high' ? 'warning' : task.priority === 'medium' ? 'info' : 'success'} variant="soft">{task.priority}</Badge>
              </div>
              {task.assigneeName && (
                <div className="flex items-center justify-between">
                  <span className="text-caption text-text-tertiary">Assignee</span>
                  <span className="text-caption font-medium text-text-primary">{task.assigneeName}</span>
                </div>
              )}
              <div className="flex items-center justify-between">
                <span className="text-caption text-text-tertiary">Created</span>
                <span className="text-caption text-text-primary">{task.createdAt}</span>
              </div>
              {task.deadline && (
                <div className="flex items-center justify-between">
                  <span className="text-caption text-text-tertiary">Due</span>
                  <span className="text-caption text-text-primary">{task.deadline}</span>
                </div>
              )}
            </CardBody>
          </Card>
        </div>
      </div>
    </div>
  );
}

function InfoRow({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-center gap-2">
      <span className="text-text-tertiary">{icon}</span>
      <div>
        <p className="text-2xs text-text-tertiary">{label}</p>
        <p className="text-caption text-text-primary">{value}</p>
      </div>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { AlertTriangle, Plus, Archive, Trash2, RotateCcw } from 'lucide-react';
import { Modal } from '../../components/ui/Modal';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Select } from '../../components/ui/Select';
import { Textarea } from '../../components/ui/Textarea';

export type TaskModalKind =
  | { kind: 'create' }
  | { kind: 'edit'; task: { id: string; title: string; description?: string } }
  | { kind: 'archive'; task: { id: string; title: string } }
  | { kind: 'restore'; task: { id: string; title: string } }
  | { kind: 'delete'; task: { id: string; title: string } }
  | null;

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1.5">
      <label className="text-caption font-medium text-text-secondary">{label}</label>
      {children}
    </div>
  );
}

const inputCls = 'cx-input h-10';

export function TaskModal({
  state,
  onClose,
  onSubmit,
}: {
  state: TaskModalKind;
  onClose: () => void;
  onSubmit: (data: { title: string; description?: string }) => void;
}) {
  if (!state) return null;
  switch (state.kind) {
    case 'create':
      return <CreateModal onClose={onClose} onSubmit={onSubmit} />;
    case 'edit':
      return <EditModal task={state.task} onClose={onClose} onSubmit={onSubmit} />;
    case 'archive':
      return <ArchiveModal task={state.task} onClose={onClose} onConfirm={() => onSubmit({ title: state.task.title })} />;
    case 'restore':
      return <RestoreModal task={state.task} onClose={onClose} onConfirm={() => onSubmit({ title: state.task.title })} />;
    case 'delete':
      return <DeleteModal task={state.task} onClose={onClose} onConfirm={() => onSubmit({ title: state.task.title })} />;
  }
}

function CreateModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (data: { title: string; description?: string }) => void }) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({ title: title.trim(), description: description.trim() || undefined });
    onClose();
  };
  return (
    <Modal
      open
      onClose={onClose}
      title="Create Task"
      description="Add a new task to this project."
      size="lg"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit} leftIcon={<Plus className="h-4 w-4" />} disabled={!title.trim()}>Create Task</Button>
        </>
      }
    >
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <Field label="Title">
          <input className={inputCls} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Enter task title" autoFocus />
        </Field>
        <Field label="Description">
          <Textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional description..." />
        </Field>
      </form>
    </Modal>
  );
}

function EditModal({ task, onClose, onSubmit }: { task: { id: string; title: string; description?: string }; onClose: () => void; onSubmit: (data: { title: string; description?: string }) => void }) {
  const [title, setTitle] = useState(task.title);
  const [description, setDescription] = useState(task.description ?? '');
  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({ title: title.trim(), description: description.trim() || undefined });
    onClose();
  };
  return (
    <Modal
      open
      onClose={onClose}
      title="Edit Task"
      description="Update task details."
      size="lg"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit} disabled={!title.trim()}>Save Changes</Button>
        </>
      }
    >
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <Field label="Title">
          <input className={inputCls} value={title} onChange={(e) => setTitle(e.target.value)} autoFocus />
        </Field>
        <Field label="Description">
          <Textarea value={description} onChange={(e) => setDescription(e.target.value)} />
        </Field>
      </form>
    </Modal>
  );
}

function ArchiveModal({ task, onClose, onConfirm }: { task: { id: string; title: string }; onClose: () => void; onConfirm: () => void }) {
  return (
    <Modal
      open
      onClose={onClose}
      size="sm"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button variant="danger" onClick={onConfirm} leftIcon={<Archive className="h-4 w-4" />}>Archive Task</Button>
        </>
      }
    >
      <div className="flex flex-col items-center gap-3 text-center py-2">
        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-warning-50 text-warning-600 dark:bg-warning-100 dark:text-warning-500">
          <AlertTriangle className="h-6 w-6" />
        </span>
        <h3 className="text-page font-semibold text-text-primary">Archive "{task.title}"?</h3>
        <p className="text-body text-text-secondary max-w-sm">
          The task will be archived and hidden from active views. You can restore it later.
        </p>
      </div>
    </Modal>
  );
}

function RestoreModal({ task, onClose, onConfirm }: { task: { id: string; title: string }; onClose: () => void; onConfirm: () => void }) {
  return (
    <Modal
      open
      onClose={onClose}
      size="sm"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={onConfirm} leftIcon={<RotateCcw className="h-4 w-4" />}>Restore Task</Button>
        </>
      }
    >
      <div className="flex flex-col items-center gap-3 text-center py-2">
        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-500">
          <RotateCcw className="h-6 w-6" />
        </span>
        <h3 className="text-page font-semibold text-text-primary">Restore "{task.title}"?</h3>
        <p className="text-body text-text-secondary max-w-sm">
          This task will be moved back to the active task list.
        </p>
      </div>
    </Modal>
  );
}

function DeleteModal({ task, onClose, onConfirm }: { task: { id: string; title: string }; onClose: () => void; onConfirm: () => void }) {
  return (
    <Modal
      open
      onClose={onClose}
      size="sm"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button variant="danger" onClick={onConfirm} leftIcon={<Trash2 className="h-4 w-4" />}>Delete Permanently</Button>
        </>
      }
    >
      <div className="flex flex-col items-center gap-3 text-center py-2">
        <span className="flex h-12 w-12 items-center justify-center rounded-full bg-danger-50 text-danger-600 dark:bg-danger-100 dark:text-danger-500">
          <Trash2 className="h-6 w-6" />
        </span>
        <h3 className="text-page font-semibold text-text-primary">Delete "{task.title}"?</h3>
        <p className="text-body text-text-secondary max-w-sm">
          This action cannot be undone. The task and all its data will be permanently deleted.
        </p>
      </div>
    </Modal>
  );
}

import { useState, useMemo, useCallback } from 'react';
import {
  Search,
  Plus,
  LayoutGrid,
  LayoutList,
  Calendar,
  ChevronDown,
  CheckCircle2,
  Clock,
  FolderKanban,
  MoreHorizontal,
  Eye,
  Edit2,
  Archive,
  RotateCcw,
  Filter,
  Trash2,
} from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge, type Tone } from '../../components/ui/Badge';
import { IconButton } from '../../components/ui/IconButton';
import { Progress } from '../../components/ui/Progress';
import { Dropdown, type DropdownItem } from '../../components/ui/Dropdown';
import { Select } from '../../components/ui/Select';
import { EmptyState } from '../../components/ui/EmptyState';
import { Skeleton } from '../../components/ui/Skeleton';
import { useToast } from '../../components/ui/Toast';
import { useNavigate } from 'react-router-dom';
import { cn } from '../../lib/cn';
import { useTasksList, useCreateTask, useUpdateTask, useDeleteTask } from '../../services/task-hooks';
import { mapTaskResponse } from './tasks-types';
import type { Task } from './tasks-types';
import { TaskModal, type TaskModalKind } from './TaskModals';

type ViewMode = 'kanban' | 'list' | 'calendar';

const taskStatuses = ['todo', 'in-progress', 'in-review', 'blocked', 'completed', 'archived'];
const statusLabels: Record<string, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  'in-review': 'In Review',
  blocked: 'Blocked',
  completed: 'Completed',
  archived: 'Archived',
};
const statusColors: Record<string, Tone> = {
  todo: 'info',
  'in-progress': 'accent',
  'in-review': 'warning',
  blocked: 'danger',
  completed: 'success',
  archived: 'neutral',
};

interface TasksPageProps {
  workspaceId?: string;
  departmentId?: string;
  projectId?: string;
}

export function TasksPage({ workspaceId = '', departmentId = '', projectId = '' }: TasksPageProps) {
  const { toast } = useToast();
  const navigate = useNavigate();
  const [viewMode, setViewMode] = useState<ViewMode>('kanban');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<'priority' | 'deadline' | 'progress'>('priority');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [modal, setModal] = useState<TaskModalKind>(null);

  const { data: tasksPage, isLoading, isError, error } = useTasksList(workspaceId, departmentId, projectId, {
    search: search || undefined,
    status: statusFilter || undefined,
  });

  const createTask = useCreateTask(workspaceId, departmentId, projectId);
  const updateTask = useUpdateTask(workspaceId, departmentId, projectId, '');
  const deleteTask = useDeleteTask(workspaceId, departmentId, projectId);

  const tasks: Task[] = useMemo(() => {
    if (!tasksPage?.content) return [];
    return tasksPage.content.map(mapTaskResponse);
  }, [tasksPage]);

  const filteredTasks = useMemo(() => {
    let result = tasks;
    if (search) {
      const q = search.toLowerCase();
      result = result.filter((t) => t.title.toLowerCase().includes(q) || t.description?.toLowerCase().includes(q));
    }
    result.sort((a, b) => {
      switch (sortBy) {
        case 'deadline':
          if (!a.deadline || !b.deadline) return 0;
          return new Date(a.deadline).getTime() - new Date(b.deadline).getTime();
        case 'progress':
          return (b.progress ?? 0) - (a.progress ?? 0);
        case 'priority':
        default: {
          const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3 };
          return priorityOrder[a.priority] - priorityOrder[b.priority];
        }
      }
    });
    return result;
  }, [tasks, search, sortBy]);

  const stats = useMemo(() => ({
    total: tasks.length,
    inProgress: tasks.filter((t) => t.status === 'in-progress').length,
    completed: tasks.filter((t) => t.status === 'completed').length,
    blocked: tasks.filter((t) => t.status === 'blocked').length,
  }), [tasks]);

  const handleModalSubmit = useCallback((data: { title: string; description?: string }) => {
    if (!modal) return;
    switch (modal.kind) {
      case 'create':
        createTask.mutate({ title: data.title, description: data.description }, {
          onSuccess: () => toast({ title: 'Task created', tone: 'success' }),
          onError: () => toast({ title: 'Failed to create task', tone: 'danger' }),
        });
        break;
      case 'edit':
        updateTask.mutate({ title: data.title, description: data.description }, {
          onSuccess: () => toast({ title: 'Task updated', tone: 'success' }),
          onError: () => toast({ title: 'Failed to update task', tone: 'danger' }),
        });
        break;
      case 'archive':
        deleteTask.mutate(modal.task.id, {
          onSuccess: () => toast({ title: 'Task archived', tone: 'success' }),
          onError: () => toast({ title: 'Failed to archive task', tone: 'danger' }),
        });
        break;
      case 'delete':
        deleteTask.mutate(modal.task.id, {
          onSuccess: () => toast({ title: 'Task deleted', tone: 'success' }),
          onError: () => toast({ title: 'Failed to delete task', tone: 'danger' }),
        });
        break;
    }
  }, [modal, createTask, updateTask, deleteTask, toast]);

  if (!workspaceId || !departmentId || !projectId) {
    return (
      <div className="flex flex-col gap-6">
        <div className="flex flex-col gap-1.5">
          <h1 className="text-page font-semibold text-text-primary">Tasks</h1>
          <p className="text-body text-text-secondary">Manage and track all tasks across your projects.</p>
        </div>
        <EmptyState icon={<FolderKanban />} title="Select a Project" description="Please navigate to a project first to view its tasks." />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex flex-col gap-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-6 w-72" />
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-lg" />)}
        </div>
        <Skeleton className="h-96 rounded-lg" />
      </div>
    );
  }

  if (isError) {
    return (
      <EmptyState
        icon={<CheckCircle2 />}
        title="Failed to load tasks"
        description={(error as Error)?.message ?? 'An error occurred while fetching tasks.'}
      />
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <TaskModal state={modal} onClose={() => setModal(null)} onSubmit={handleModalSubmit} />

      <div className="flex flex-col gap-1.5">
        <h1 className="text-page font-semibold text-text-primary">Tasks</h1>
        <p className="text-body text-text-secondary">Manage and track all tasks across your projects.</p>
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatCard label="Total Tasks" value={stats.total} tone="accent" />
        <StatCard label="In Progress" value={stats.inProgress} tone="info" />
        <StatCard label="Completed" value={stats.completed} tone="success" />
        <StatCard label="Blocked" value={stats.blocked} tone="danger" />
      </div>

      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 flex-col gap-2 sm:flex-row sm:gap-2">
          <div className="flex-1">
            <Input
              placeholder="Search tasks..."
              leftIcon={<Search />}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              containerClassName="w-full"
            />
          </div>
          <Select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            options={[
              { value: '', label: 'All Statuses' },
              ...taskStatuses.map((s) => ({ value: s, label: statusLabels[s] })),
            ]}
            placeholder="Status"
          />
          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                Sort
                <ChevronDown className="h-3.5 w-3.5" />
              </Button>
            }
            items={[
              { label: 'Priority', onClick: () => setSortBy('priority') },
              { label: 'Deadline', onClick: () => setSortBy('deadline') },
              { label: 'Progress', onClick: () => setSortBy('progress') },
            ]}
          />
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <div className="flex items-center gap-1 border border-border-subtle rounded-lg p-1">
            <IconButton label="Kanban view" variant={viewMode === 'kanban' ? 'solid' : 'ghost'} onClick={() => setViewMode('kanban')} className="h-8 w-8">
              <LayoutGrid className="h-4 w-4" />
            </IconButton>
            <IconButton label="List view" variant={viewMode === 'list' ? 'solid' : 'ghost'} onClick={() => setViewMode('list')} className="h-8 w-8">
              <LayoutList className="h-4 w-4" />
            </IconButton>
            <IconButton label="Calendar view" variant={viewMode === 'calendar' ? 'solid' : 'ghost'} onClick={() => setViewMode('calendar')} className="h-8 w-8">
              <Calendar className="h-4 w-4" />
            </IconButton>
          </div>
          <Button leftIcon={<Plus />} onClick={() => setModal({ kind: 'create' })}>Create Task</Button>
        </div>
      </div>

      {filteredTasks.length === 0 && !isLoading ? (
        <EmptyState icon={<CheckCircle2 />} title="No tasks found" description="Try adjusting your search or filters to find tasks." />
      ) : viewMode === 'kanban' ? (
        <KanbanView tasks={filteredTasks} onTaskClick={(id) => navigate(`/app/tasks/${id}?ws=${workspaceId}&dept=${departmentId}&proj=${projectId}`)} onEdit={(task) => setModal({ kind: 'edit', task })} onArchive={(task) => setModal({ kind: 'archive', task })} />
      ) : viewMode === 'list' ? (
        <ListView tasks={filteredTasks} onTaskClick={(id) => navigate(`/app/tasks/${id}?ws=${workspaceId}&dept=${departmentId}&proj=${projectId}`)} onEdit={(task) => setModal({ kind: 'edit', task })} onArchive={(task) => setModal({ kind: 'archive', task })} />
      ) : (
        <CalendarView tasks={filteredTasks} onTaskClick={(id) => navigate(`/app/tasks/${id}?ws=${workspaceId}&dept=${departmentId}&proj=${projectId}`)} onEdit={(task) => setModal({ kind: 'edit', task })} onArchive={(task) => setModal({ kind: 'archive', task })} />
      )}
    </div>
  );
}

function StatCard({ label, value, tone }: { label: string; value: number; tone: string }) {
  const bgColor: Record<string, string> = {
    accent: 'bg-accent-50 dark:bg-accent-100 text-accent-700 dark:text-accent-200',
    success: 'bg-success-50 dark:bg-success-100 text-success-700 dark:text-success-200',
    info: 'bg-info-50 dark:bg-info-100 text-info-700 dark:text-info-200',
    warning: 'bg-warning-50 dark:bg-warning-100 text-warning-700 dark:text-warning-200',
    danger: 'bg-danger-50 dark:bg-danger-100 text-danger-700 dark:text-danger-200',
  };
  return (
    <div className={cn('rounded-lg border border-border-subtle p-3', bgColor[tone] ?? bgColor.accent)}>
      <p className="text-2xs font-medium opacity-75">{label}</p>
      <p className="text-section font-semibold mt-1">{value}</p>
    </div>
  );
}

function KanbanView({ tasks, onTaskClick, onEdit, onArchive }: { tasks: Task[]; onTaskClick: (id: string) => void; onEdit: (task: { id: string; title: string; description?: string }) => void; onArchive: (task: { id: string; title: string }) => void }) {
  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-6 overflow-x-auto pb-4">
      {taskStatuses.filter(s => s !== 'archived').map((status) => {
        const statusTasks = tasks.filter((t) => t.status === status);
        return (
          <div key={status} className="flex flex-col gap-3 min-w-[300px] sm:min-w-[320px]">
            <div className="flex items-center justify-between px-3 py-2">
              <div className="flex items-center gap-2">
                <Badge tone={statusColors[status]} variant="soft" dot>
                  {statusLabels[status]}
                </Badge>
                <span className="text-2xs font-semibold text-text-tertiary">{statusTasks.length}</span>
              </div>
            </div>
            <div className="flex flex-col gap-2">
              {statusTasks.length === 0 ? (
                <div className="rounded-lg border-2 border-dashed border-border-subtle bg-surface p-4 text-center">
                  <p className="text-2xs text-text-tertiary">No tasks</p>
                </div>
              ) : (
                statusTasks.map((task) => <TaskCard key={task.id} task={task} onClick={() => onTaskClick(task.id)} onEdit={() => onEdit(task)} onArchive={() => onArchive(task)} />)
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function TaskCard({ task, onClick, onEdit, onArchive }: { task: Task; onClick: () => void; onEdit: () => void; onArchive: () => void }) {
  const priorityColor: Record<string, Tone> = { urgent: 'danger', high: 'warning', medium: 'info', low: 'success' };
  const actionItems: DropdownItem[] = [
    { label: 'Open', icon: <Eye className="h-4 w-4" />, onClick },
    { label: 'Edit', icon: <Edit2 className="h-4 w-4" />, onClick: onEdit },
    { divider: true },
    { label: 'Archive', icon: <Archive className="h-4 w-4" />, onClick: onArchive },
  ];
  return (
    <Card className="hover:border-border-default transition-colors cursor-pointer group">
      <CardBody className="space-y-2" onClick={onClick}>
        <div className="flex items-start justify-between gap-2">
          <h4 className="text-body font-medium text-text-primary line-clamp-2 flex-1">{task.title}</h4>
          <Dropdown
            trigger={
              <IconButton label="Actions" variant="ghost" size="sm" onClick={(e: React.MouseEvent) => e.stopPropagation()}>
                <MoreHorizontal className="h-4 w-4" />
              </IconButton>
            }
            items={actionItems}
            align="right"
          />
        </div>
        {task.description && <p className="text-2xs text-text-tertiary line-clamp-2">{task.description}</p>}
        <div className="flex items-center justify-between gap-2">
          <Badge tone={priorityColor[task.priority]} variant="soft">{task.priority}</Badge>
        </div>
        {task.deadline && (
          <div className="flex items-center gap-1.5 text-2xs text-text-tertiary">
            <Clock className="h-3 w-3" />
            <span>{task.deadline}</span>
          </div>
        )}
      </CardBody>
    </Card>
  );
}

function ListView({ tasks, onTaskClick, onEdit, onArchive }: { tasks: Task[]; onTaskClick: (id: string) => void; onEdit: (task: { id: string; title: string; description?: string }) => void; onArchive: (task: { id: string; title: string }) => void }) {
  return (
    <div className="space-y-2">
      {tasks.filter(t => t.status !== 'archived').map((task) => <TaskListRow key={task.id} task={task} onClick={() => onTaskClick(task.id)} onEdit={() => onEdit(task)} onArchive={() => onArchive(task)} />)}
    </div>
  );
}

function TaskListRow({ task, onClick, onEdit, onArchive }: { task: Task; onClick: () => void; onEdit: () => void; onArchive: () => void }) {
  const priorityColor: Record<string, Tone> = { urgent: 'danger', high: 'warning', medium: 'info', low: 'success' };
  const statusColor: Record<string, Tone> = { todo: 'info', 'in-progress': 'accent', 'in-review': 'warning', blocked: 'danger', completed: 'success', archived: 'neutral' };
  const actionItems: DropdownItem[] = [
    { label: 'Open', icon: <Eye className="h-4 w-4" />, onClick },
    { label: 'Edit', icon: <Edit2 className="h-4 w-4" />, onClick: onEdit },
    { divider: true },
    { label: 'Archive', icon: <Archive className="h-4 w-4" />, onClick: onArchive },
  ];
  return (
    <div className="flex items-center gap-4 rounded-lg border border-border-subtle bg-surface p-3 hover:bg-surface-2 transition-colors group cursor-pointer" onClick={onClick}>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-2">
          <h4 className="text-body font-medium text-text-primary truncate flex-1">{task.title}</h4>
          <Badge tone={statusColor[task.status]} variant="soft" dot>{statusLabels[task.status]}</Badge>
        </div>
        <div className="flex items-center gap-2 text-caption text-text-secondary">
          {task.deadline && <span>{task.deadline}</span>}
        </div>
      </div>
      <div className="flex items-center gap-3">
        <Badge tone={priorityColor[task.priority]} variant="soft">{task.priority}</Badge>
        <Dropdown
          trigger={
            <IconButton label="Actions" variant="ghost" size="sm" onClick={(e: React.MouseEvent) => e.stopPropagation()}>
              <MoreHorizontal className="h-4 w-4" />
            </IconButton>
          }
          items={actionItems}
          align="right"
        />
      </div>
    </div>
  );
}

function CalendarView({ tasks, onTaskClick }: { tasks: Task[]; onTaskClick: (id: string) => void; onEdit: (task: { id: string; title: string; description?: string }) => void; onArchive: (task: { id: string; title: string }) => void }) {
  const tasksByDate: Record<string, Task[]> = {};
  tasks.forEach((task) => {
    if (task.deadline) {
      if (!tasksByDate[task.deadline]) tasksByDate[task.deadline] = [];
      tasksByDate[task.deadline].push(task);
    }
  });
  const sortedDates = Object.keys(tasksByDate).sort();
  if (sortedDates.length === 0) {
    return (
      <Card><CardBody className="py-8 text-center"><p className="text-body text-text-secondary">No upcoming deadlines</p></CardBody></Card>
    );
  }
  return (
    <div className="space-y-4">
      {sortedDates.map((date) => (
        <div key={date}>
          <div className="flex items-center gap-3 mb-2 px-2">
            <Calendar className="h-4 w-4 text-text-tertiary" />
            <h3 className="text-caption font-semibold text-text-primary">{date}</h3>
            <Badge tone="neutral" variant="soft">{tasksByDate[date].length} task{tasksByDate[date].length !== 1 ? 's' : ''}</Badge>
          </div>
          <div className="space-y-2">
            {tasksByDate[date].map((task) => (
              <div key={task.id} className="flex items-center gap-4 rounded-lg border border-border-subtle bg-surface p-3 hover:bg-surface-2 transition-colors group cursor-pointer" onClick={() => onTaskClick(task.id)}>
                <div className="flex-1 min-w-0">
                  <h4 className="text-body font-medium text-text-primary truncate">{task.title}</h4>
                </div>
                <Badge tone={statusColors[task.status]} variant="soft" dot>{statusLabels[task.status]}</Badge>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

